import React from 'react'
import { useAuth } from '../contexts/AuthContext'
import { useNavigate } from 'react-router-dom'
import { 
  LogOut, 
  User, 
  Bell, 
  Shield, 
  Globe, 
  ChevronRight,
  Moon,
  Sun,
  Lock,
  HelpCircle
} from 'lucide-react'

export default function Settings() {
    const { user, signOut } = useAuth()
    const navigate = useNavigate()

    const handleSignOut = async () => {
        await signOut()
        navigate('/login')
    }

    const settingsSections = [
        {
            title: 'Account',
            items: [
                { icon: User, label: 'Edit Profile', onClick: () => navigate('/profile') },
                { icon: Bell, label: 'Notifications', onClick: () => {} },
                { icon: Lock, label: 'Privacy', onClick: () => {} },
            ]
        },
        {
            title: 'Preferences',
            items: [
                { icon: Sun, label: 'Theme', onClick: () => {} },
                { icon: Globe, label: 'Language', onClick: () => {} },
            ]
        },
        {
            title: 'Support',
            items: [
                { icon: HelpCircle, label: 'Help & Feedback', onClick: () => {} },
                { icon: Shield, label: 'Privacy Policy', onClick: () => {} },
            ]
        }
    ]

    return (
        <div className="min-h-screen bg-gray-50 px-4 py-6 pb-20">
            <h1 className="text-2xl font-bold text-gray-800 mb-6">Settings</h1>

            {settingsSections.map((section) => (
                <div key={section.title} className="mb-6">
                    <h2 className="text-sm font-medium text-gray-500 uppercase tracking-wider mb-2 px-2">
                        {section.title}
                    </h2>
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                        {section.items.map((item, index) => {
                            const Icon = item.icon
                            return (
                                <button
                                    key={index}
                                    onClick={item.onClick}
                                    className={`w-full flex items-center justify-between px-4 py-3 hover:bg-gray-50 transition ${
                                        index !== section.items.length - 1 ? 'border-b border-gray-100' : ''
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <Icon size={18} className="text-gray-500" />
                                        <span className="text-gray-700 font-medium">{item.label}</span>
                                    </div>
                                    <ChevronRight size={18} className="text-gray-400" />
                                </button>
                            )
                        })}
                    </div>
                </div>
            ))}

            <button
                onClick={handleSignOut}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-red-50 text-red-600 rounded-xl font-medium hover:bg-red-100 transition"
            >
                <LogOut size={18} />
                Sign Out
            </button>

            <div className="text-center mt-6">
                <p className="text-xs text-gray-400">PredictFC v1.0.0</p>
                <p className="text-xs text-gray-400 mt-1">{user?.email}</p>
            </div>
        </div>
    )
}
